  "swiggy.com": { name: "Swiggy", zh: "印度最大外卖平台之一，提供餐馆外卖与即时配送服务。", en: "One of India's largest food delivery platforms offering restaurant delivery and quick commerce." },
  "meituan.com": { name: "美团", zh: "中国领先的生活服务平台，覆盖外卖、到店、酒店旅游、共享单车等业务。", en: "China's leading life-services platform covering food delivery, in-store, travel, and bike sharing." },
  "eleme.cn": { name: "饿了么", zh: "阿里巴巴旗下的本地生活外卖平台，是中国两大外卖平台之一。", en: "Alibaba's local-life delivery platform, one of China's two dominant food delivery apps." },
