  "deezer.com": { name: "Deezer", zh: "欧洲知名音乐流媒体平台，提供海量曲库与个性化播放列表。", en: "A prominent European music streaming platform offering a vast catalog and personalized playlists." },
  "qqmusic.qq.com": { name: "QQ音乐", zh: "腾讯旗下的在线音乐平台，中国最大的音乐流媒体服务之一。", en: "Tencent's online music platform, one of China's largest music streaming services." },
  "netease.com": { name: "网易", zh: "中国领先的互联网公司，运营网易新闻、网易邮箱、网易云音乐、网易游戏等业务。", en: "A leading Chinese internet company running NetEase News, Mail, Cloud Music, and games." },
  "godaddy.com": { name: "GoDaddy", zh: "全球最大的域名注册商之一，同时提供虚拟主机、建站工具和网络安全服务，管理超过 8000 万个域名。", en: "One of the world's largest domain registrars, also offering web hosting, website builders, and cybersecurity services, managing over 80 million domain names." },
  "namecheap.com": { name: "Namecheap", zh: "全球知名的域名注册商，以低价和优质客服著称，同时提供主机、SSL 证书和隐私保护等配套服务。", en: "A globally known domain registrar renowned for competitive pricing and quality support, also offering hosting, SSL certificates, and privacy protection." },
  "dynadot.com": { name: "Dynadot", zh: "美国知名域名注册商，以优惠的域名价格和简单的管理界面著称。", en: "A US domain registrar known for competitive pricing and a simple management interface." },
  "name.com": { name: "Name.com", zh: "老牌域名注册商，提供域名注册、托管、SSL 及建站服务。", en: "A long-standing domain registrar offering registration, hosting, SSL, and site-building services." },
