  "wix.com": { name: "Wix", zh: "全球知名网站构建平台，通过拖拽工具帮助用户快速建站。", en: "A globally known website builder letting users create sites quickly with drag-and-drop tools." },
  "squarespace.com": { name: "Squarespace", zh: "以精美模板著称的建站平台，适合创意人士和小企业搭建品牌网站。", en: "A website platform known for beautiful templates, ideal for creatives and small businesses." },
