  "harvard.edu": { name: "Harvard", zh: "哈佛大学，美国最古老、最负盛名的常春藤盟校。", en: "Harvard University, America's oldest and most prestigious Ivy League university." },
  "stanford.edu": { name: "Stanford", zh: "斯坦福大学，位于硅谷的世界顶尖研究型大学。", en: "Stanford University, a world-leading research university in the heart of Silicon Valley." },
  "ox.ac.uk": { name: "牛津大学", zh: "牛津大学，英语世界最古老的大学，位于英国牛津。", en: "University of Oxford, the oldest university in the English-speaking world." },
  "cam.ac.uk": { name: "剑桥大学", zh: "剑桥大学，英国最负盛名的研究型大学之一，与牛津并称。", en: "University of Cambridge, one of the UK's most prestigious research universities." },
  "iana.org": { name: "IANA", zh: "互联网号码分配局，负责全球 IP 地址、域名根区和互联网协议参数的协调与分配，是互联网基础架构的核心管理机构。", en: "The Internet Assigned Numbers Authority, responsible for coordinating global IP addresses, the domain name root zone, and Internet protocol parameters—a core internet governance body." },
  "icann.org": { name: "ICANN", zh: "互联网名称与数字地址分配机构，负责管理全球域名系统（DNS）政策、新顶级域（gTLD）批准及互联网地址资源分配。", en: "The Internet Corporation for Assigned Names and Numbers, governing global DNS policy, new gTLD approvals, and internet address resource allocation." },
  "w3.org": { name: "W3C", zh: "万维网联盟，HTML、CSS、SVG 等 Web 核心标准的制定机构，致力于引导万维网向开放、可访问、可互操作的方向发展。", en: "The World Wide Web Consortium, the body that sets core web standards including HTML, CSS, and SVG, guiding the web toward openness, accessibility, and interoperability." },
  "ietf.org": { name: "IETF", zh: "互联网工程任务组，负责制定互联网核心技术标准（如 TCP/IP、HTTP）。", en: "The Internet Engineering Task Force, which develops core internet standards like TCP/IP and HTTP." },
  "iso.org": { name: "ISO", zh: "国际标准化组织，全球最大的标准制定机构，发布各行业国际标准。", en: "The International Organization for Standardization, the world's largest developer of international standards." },
