  "kuaishou.com": { name: "快手", zh: "中国领先的短视频和直播平台，以普惠内容和庞大下沉市场用户著称。", en: "A leading Chinese short-video and live-streaming platform known for inclusive content and mass-market reach." },
  "douyu.com": { name: "斗鱼", zh: "中国领先的游戏直播平台，以电竞、主机与娱乐直播内容著称。", en: "A leading Chinese game live-streaming platform known for esports and entertainment streams." },
  "huya.com": { name: "虎牙", zh: "中国头部游戏直播平台，腾讯旗下，专注电竞与游戏直播。", en: "A top Chinese game live-streaming platform under Tencent, focused on esports and gaming." },
